  def icon(name, css = "h-5 w-5", stroke: 1.7)
    path = ICONS.fetch(name.to_sym)
    tag.svg(xmlns: "http://www.w3.org/2000/svg", fill: "none", viewBox: "0 0 24 24", "stroke-width": stroke,
            stroke: "currentColor", class: css, "aria-hidden": "true") do
